    def minimumSum(self, n: int, k: int) -> int:
        ans = 0

        if n > k // 2:
            # Take the first k//2 numbers (1 to k//2)
            for i in range(1, k // 2 + 1):
                ans += i

            # Take the next (n - k//2) numbers starting from k//2 + 1
            # But skip any number that forms a pair summing to k with previously taken numbers
            start = k // 2 + 1
            count = 0
            while count < n - k // 2:
                if k - start != 0 and k - start <= k // 2:
                    # This number would form a pair with some previously taken number
                    start += 1
                else:
                    ans += start
                    start += 1
                    count += 1
        else:
            # Take the first n numbers
            for i in range(1, n + 1):
                ans += i

        return ans

